  <script>
    (() => {
      const body = document.body;
      const button = document.getElementById("theme-toggle");
      const icon = document.getElementById("theme-icon");
      const label = document.getElementById("theme-label");
      const year = document.getElementById("current-year");

      year.textContent = new Date().getFullYear();

      let savedTheme = null;
      try {
        savedTheme = localStorage.getItem("team-theme");
      } catch (_) {
        // Keep the default day theme when storage is unavailable.
      }

      const applyTheme = (theme) => {
        const isNight = theme === "night";
        body.dataset.theme = isNight ? "night" : "day";
        icon.textContent = isNight ? "☀" : "☾";
        label.textContent = isNight ? "Day mode" : "Night mode";
        button.setAttribute("aria-label", isNight ? "Switch to day mode" : "Switch to night mode");
      };

      applyTheme(savedTheme === "night" ? "night" : "day");

      button.addEventListener("click", () => {
        const nextTheme = body.dataset.theme === "night" ? "day" : "night";
        applyTheme(nextTheme);
        try {
          localStorage.setItem("team-theme", nextTheme);
        } catch (_) {
          // The toggle still works for this visit if storage is unavailable.
        }
      });
    })();
  </script>
